<template><section class="cost-page"><header class="cost-page-heading"><div><h2>قیمت مواد اولیه</h2><p>قیمت فعلی و واحد اندازه‌گیری مواد مصرفی را مدیریت کنید.</p></div><button class="cost-primary" @click="openCreate">ماده اولیه جدید</button></header><form class="cost-filter" @submit.prevent="search"><input v-model.trim="query" placeholder="جستجوی نام ماده اولیه" @input="debouncedSearch"/><select v-model="activeFilter" @change="search"><option value="">همه وضعیت‌ها</option><option value="true">فعال</option><option value="false">غیرفعال</option></select><button class="cost-primary">جستجو</button></form><div v-if="error" class="cost-notice" role="alert">{{error}} <button @click="load">تلاش مجدد</button></div><div class="materials-table"><header><span>ماده اولیه</span><span>واحد</span><span>قیمت هر واحد</span><span>وضعیت</span><span>عملیات</span></header><article v-for="item in ingredients" :key="item.id"><strong>{{item.name}}</strong><span>{{item.unit_display}}</span><strong>{{money(item.unit_cost)}}</strong><span :class="['status',item.is_active?'on':'off']">{{item.is_active?'فعال':'غیرفعال'}}</span><footer><button class="row-action" @click="openEdit(item)">ویرایش قیمت</button><button class="danger-action" @click="remove(item)">حذف</button></footer></article><div v-if="loading" class="empty-resource">در حال دریافت مواد اولیه…</div><div v-else-if="!ingredients.length" class="empty-resource">ماده اولیه‌ای پیدا نشد.</div></div><div class="resource-pagination" v-if="pagination.total_pages>1"><button class="cost-secondary" :disabled="!pagination.has_previous" @click="goPage(pagination.page-1)">قبلی</button><span>صفحه {{number(pagination.page)}} از {{number(pagination.total_pages)}}</span><button class="cost-secondary" :disabled="!pagination.has_next" @click="goPage(pagination.page+1)">بعدی</button></div><IngredientModal v-model="modalOpen" :ingredient="editing" :units="meta.units" :loading="saving" :server-error="modalError" :field-errors="fieldErrors" @submit="save"/></section></template>
<script setup>import{onBeforeUnmount,onMounted,reactive,ref}from'vue';import API from'@/api/product-cost.api.js';import IngredientModal from'@/components/modals/IngredientModal.vue';import{costErrorMessage,formatCostNumber as number,formatMoney as money}from'@/utils/costControl';const ingredients=ref([]),query=ref(''),activeFilter=ref(''),editing=ref(null),modalOpen=ref(false),loading=ref(false),saving=ref(false),error=ref(''),modalError=ref(''),fieldErrors=ref({}),meta=reactive({units:[]}),pagination=reactive({page:1,page_size:10,total_pages:1,has_next:false,has_previous:false});let timer;async function load(){loading.value=true;error.value='';try{const[metadata,data]=await Promise.all([meta.units.length?Promise.resolve(meta):API.meta(),API.ingredients({search:query.value,is_active:activeFilter.value,page:pagination.page,page_size:pagination.page_size})]);Object.assign(meta,metadata);ingredients.value=data.results||[];Object.assign(pagination,data)}catch(cause){error.value=costErrorMessage(cause)}finally{loading.value=false}}function openCreate(){editing.value=null;modalError.value='';fieldErrors.value={};modalOpen.value=true}function openEdit(item){editing.value=item;modalError.value='';fieldErrors.value={};modalOpen.value=true}async function save(payload){saving.value=true;modalError.value='';fieldErrors.value={};try{if(editing.value)await API.updateIngredient(editing.value.id,payload);else await API.createIngredient(payload);modalOpen.value=false;await load()}catch(cause){modalError.value=costErrorMessage(cause);fieldErrors.value=cause.cost?.errors||{}}finally{saving.value=false}}async function remove(item){if(!confirm(`ماده اولیه «${item.name}» حذف شود؟`))return;try{await API.deleteIngredient(item.id);await load()}catch(cause){error.value=costErrorMessage(cause)}}function search(){pagination.page=1;load()}function debouncedSearch(){clearTimeout(timer);timer=setTimeout(search,400)}function goPage(page){pagination.page=page;load()}onMounted(load);onBeforeUnmount(()=>clearTimeout(timer))</script>
<style scoped>.materials-table{overflow:hidden;background:var(--surface);border:1px solid var(--border);border-radius:13px}.materials-table>header,.materials-table>article{display:grid;grid-template-columns:minmax(170px,1.4fr) repeat(3,minmax(110px,1fr)) 180px;align-items:center;gap:12px;padding:12px 16px}.materials-table>header{background:var(--surface-subtle);color:var(--muted);font-size:.72rem}.materials-table>article{border-top:1px solid var(--border);font-size:.8rem}.materials-table footer{display:flex}.materials-table>.empty-resource{border-top:1px solid var(--border)}@media(max-width:760px){.materials-table>header{display:none}.materials-table>article{grid-template-columns:repeat(2,minmax(0,1fr))}.materials-table footer{justify-self:end}}@media(max-width:480px){.materials-table>article{grid-template-columns:1fr}.materials-table footer{justify-self:start}}</style>
